-- A pair of the campaign on MySQL 9.7.4 (seed 144, --rich; rules LEFT->INNER-JOIN, cmp-weaken,
-- cond->FALSE, cond->TRUE), as bridge/reduce_mysql.py left it.
-- CAST(date AS SIGNED) is 20240101 or more, never 1, so NOT EXISTS (...) is true for every
-- row of t3; the derived table has the 11 rows of t1; the join condition is true.
-- expected: 55 rows in every line
DROP DATABASE IF EXISTS vs_lj; CREATE DATABASE vs_lj; USE vs_lj;
CREATE TABLE t1 (c1 VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci, c4 DATE);
INSERT INTO t1 VALUES (' 1', '2024-02-15'), ('3', '2024-12-01'), ('4', '2024-01-15'), ('a', NULL), ('a', '2024-01-01'),
  ('a', '2024-01-01'), ('a', '2024-12-15'), ('b', '2024-01-01'), ('b', '2024-12-01'), ('x', '2024-02-01'), ('x', '2024-02-01');
CREATE TABLE t3 (c1 VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin, c6 DATE);
INSERT INTO t3 VALUES ('4', '2024-01-01'), (NULL, '2024-12-01'), ('b', '2024-12-01'), ('7', '2024-01-15'), ('B', '2024-12-01');
SELECT 'LEFT JOIN, = 1' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1))) AS r;
SELECT 'INNER JOIN, = 1' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a INNER JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1))) AS r;
SELECT 'LEFT JOIN, <= 1' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) <= 1))) AS r;
SELECT 'LEFT JOIN, no derived EXISTS' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1))) AS r;
SELECT 'LEFT JOIN, table' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN t1 AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1))) AS r;
SELECT 'LEFT JOIN, no WHERE' AS q, COUNT(*) FROM (SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1)) AS r;
-- the rows themselves, without the COUNT wrapper
SELECT 'LEFT rows' AS q, t1b.c1 AS k0, t3a.c1 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1));
SELECT 'INNER rows' AS q, t1b.c1 AS k0, t3a.c1 FROM t3 AS t3a INNER JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1));
EXPLAIN FORMAT=TREE SELECT t1b.c1 AS k0 FROM t3 AS t3a LEFT JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1));
EXPLAIN FORMAT=TREE SELECT t1b.c1 AS k0 FROM t3 AS t3a INNER JOIN (SELECT x.c1 AS c1 FROM t1 AS x WHERE EXISTS (SELECT s.c1 FROM t1 AS s)) AS t1b ON (1) WHERE NOT (EXISTS (SELECT u.c1 FROM t3 AS u WHERE (CAST(t3a.c6 AS SIGNED)) = 1));
DROP DATABASE vs_lj;
